### 6.1 栈

栈是后进先出（LIFO）。Python list 当栈：`append`/`pop` O(1)。

括号匹配：

```python
def is_valid(s):
    pair = {')':'(', ']':'[', '}':'{'}
    st = []
    for ch in s:
        if ch in '([{':
            st.append(ch)
        else:
            if not st or st.pop() != pair[ch]:
                return False
    return not st

print(is_valid('({[]})'))
```

表达式求值（后缀/逆波兰）：

```python
def eval_rpn(tokens):
    st = []
    for t in tokens:
        if t in '+-*/':
            b = st.pop(); a = st.pop()
            if t == '+': st.append(a+b)
            elif t == '-': st.append(a-b)
            elif t == '*': st.append(a*b)
            else: st.append(int(a/b))
        else:
            st.append(int(t))
    return st[0]

print(eval_rpn(['2','1','+','3','*']))
```

### 6.2 队列与优先队列

队列先进先出（FIFO）。list.pop(0) 是 O(n)，用 `collections.deque` 是 O(1)。

```python
from collections import deque
q = deque()
q.append(1); q.append(2)
print(q.popleft())
```

优先队列用 `heapq`（最小堆）：

```python
import heapq
heap = []
heapq.heappush(heap, 3); heapq.heappush(heap, 1); heapq.heappush(heap, 2)
print(heapq.heappop(heap))
```

### 6.3 链表

```python
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class LinkedList:
    def __init__(self):
        self.head = None
    def push_front(self, val):
        self.head = ListNode(val, self.head)
    def push_back(self, val):
        if not self.head:
            self.head = ListNode(val); return
        p = self.head
        while p.next: p = p.next
        p.next = ListNode(val)
    def delete(self, target):
        dummy = ListNode(0, self.head)
        p = dummy
        while p.next:
            if p.next.val == target:
                p.next = p.next.next
                break
            p = p.next
        self.head = dummy.next
    def to_list(self):
        r = []
        p = self.head
        while p:
            r.append(p.val); p = p.next
        return r

ll = LinkedList()
ll.push_back(1); ll.push_back(2); ll.push_front(0)
ll.delete(1)
print(ll.to_list())
```

### 6.4 二叉树与遍历

```python
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def preorder(root):
    if not root: return []
    return [root.val] + preorder(root.left) + preorder(root.right)

def inorder(root):
    if not root: return []
    return inorder(root.left) + [root.val] + inorder(root.right)

def postorder(root):
    if not root: return []
    return postorder(root.left) + postorder(root.right) + [root.val]

from collections import deque
def levelorder(root):
    if not root: return []
    q = deque([root]); r = []
    while q:
        node = q.popleft()
        r.append(node.val)
        if node.left: q.append(node.left)
        if node.right: q.append(node.right)
    return r
```

二叉搜索树（BST）插入：

```python
def bst_insert(root, val):
    if not root:
        return TreeNode(val)
    if val < root.val:
        root.left = bst_insert(root.left, val)
    else:
        root.right = bst_insert(root.right, val)
    return root

def bst_search(root, val):
    if not root or root.val == val:
        return root
    if val < root.val:
        return bst_search(root.left, val)
    return bst_search(root.right, val)
```

### 6.5 堆与堆排序

```python
def heapify(arr, n, i):
    largest = i
    l, r = 2*i+1, 2*i+2
    if l < n and arr[l] > arr[largest]:
        largest = l
    if r < n and arr[r] > arr[largest]:
        largest = r
    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

def heap_sort(arr):
    a = arr[:]
    n = len(a)
    for i in range(n//2-1, -1, -1):
        heapify(a, n, i)
    for i in range(n-1, 0, -1):
        a[0], a[i] = a[i], a[0]
        heapify(a, i, 0)
    return a

print(heap_sort([3,1,4,1,5,9,2,6]))
```

### 6.6 并查集

```python
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0]*n
    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb: return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True
```

路径压缩 + 按秩合并后近似 O(α(n))，α 是阿克曼反函数，增长极慢。

